var SK_W=20, SK_H=20, SK_CELL=16;
function skNew(w,h){
  w=w||SK_W; h=h||SK_H;
  var snake=[[Math.floor(w/2),Math.floor(h/2)],[Math.floor(w/2)-1,Math.floor(h/2)]];
  var s={ w:w, h:h, snake:snake, dir:[1,0], food:null, score:0, over:false };
  skSpawnFood(s); return s;
}
function skSpawnFood(s){
  var occ={}; s.snake.forEach(function(c){ occ[c[0]+','+c[1]]=1; });
  var free=[];
  for(var y=0;y<s.h;y++) for(var x=0;x<s.w;x++) if(!occ[x+','+y]) free.push([x,y]);
  if(!free.length){ s.food=null; return; }
  s.food=free[Math.floor(Math.random()*free.length)];
}
function skSetDir(s, d){
  if(s.over) return;
  if(s.dir[0]===-d[0] && s.dir[1]===-d[1]) return; // no reverse
  s.dir=d;
}
function skStep(s){
  if(s.over) return s;
  var head=s.snake[0], nx=head[0]+s.dir[0], ny=head[1]+s.dir[1];
  if(nx<0||nx>=s.w||ny<0||ny>=s.h){ s.over=true; return s; }
  for(var i=0;i<s.snake.length;i++){ if(s.snake[i][0]===nx&&s.snake[i][1]===ny){ s.over=true; return s; } }
  s.snake.unshift([nx,ny]);
  if(s.food && nx===s.food[0] && ny===s.food[1]){ s.score++; skSpawnFood(s); }
  else { s.snake.pop(); }
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { SK_W:SK_W, SK_H:SK_H, skNew:skNew, skSpawnFood:skSpawnFood, skSetDir:skSetDir, skStep:skStep };
}
if (typeof window !== 'undefined') {
  window.SnakeForgePure = { SK_W:SK_W, SK_H:SK_H, skNew:skNew, skSpawnFood:skSpawnFood, skSetDir:skSetDir, skStep:skStep };
}
